<?php require_once __DIR__.'/../includes/functions.php';require_once __DIR__.'/includes/content.php';$pdo=get_db();$pageTitle='Polling NEXADIPTA 21';$activePage='polling';$polls=$pdo->query("SELECT id,title,poll_type,status,description FROM polls WHERE status IN ('active','scheduled','paused') ORDER BY id DESC")->fetchAll();include __DIR__.'/includes/header.php';?><section class="page-hero"><div class="container"><span class="section-kicker">POLLING ANGKATAN</span><h1>Suara kalian tetap penting.</h1><p>Ikuti polling resmi melalui sistem SKANEXA. Peserta terdaftar akan diverifikasi sebelum dapat mengikuti polling.</p></div></section><section class="section"><div class="container poll-list"><?php foreach($polls as $p): ?><article class="poll-card"><span class="poll-status"><?= strtoupper(e($p['poll_type'])) ?></span><h3><?= e($p['title']) ?></h3><p><?= e($p['description'] ?: 'Polling angkatan yang sedang tersedia.') ?></p><a class="btn btn-primary" href="/poll.php">Buka Polling →</a></article><?php endforeach; ?><?php if(!$polls): ?><div class="empty-card">Belum ada polling yang sedang tersedia.</div><?php endif; ?></div></section><?php include __DIR__.'/includes/footer.php';?>
